def render_fx_diagnostics(diag: dict, only_full_fx_windows: bool) -> None:
    with st.expander("FX conversion review", expanded=False):
        if diag["output_currency"] == "USD":
            st.write("USD output uses the raw embedded return series with no FX translation.")
            return

        coverage_start = diag["fx_coverage_start"].strftime("%Y-%m") if diag["fx_coverage_start"] is not None else "n/a"
        coverage_end = diag["fx_coverage_end"].strftime("%Y-%m") if diag["fx_coverage_end"] is not None else "n/a"
        uplift = diag["combined_geo_return_local"] - diag["asset_geo_return_usd"]
        filter_text = "ON - rolling windows with incomplete FX translation are excluded" if only_full_fx_windows else "OFF - older windows are retained with zero FX movement where FX is missing"

        st.markdown(
            f"""
**Method used**
- Embedded S&P return series is treated as **USD-denominated monthly asset return**.
- FX series **{diag['fx_series']}** is inverted to get local currency per USD.
- Monthly local return is computed as **(1 + asset return) × (1 + FX return) − 1**.
- FX full-coverage filter: **{filter_text}**.

**Coverage**
- FX coverage window: **{coverage_start}** to **{coverage_end}**
- Months with active FX translation: **{diag['covered_months']:,}** of **{diag['total_months']:,}**
- Months without consecutive FX observations: **{diag['missing_fx_months']:,}**

**Annualised diagnostic**
- Asset-only geometric return in USD: **{diag['asset_geo_return_usd']*100:.2f}%**
- FX-only geometric return in {diag['output_currency']}: **{diag['fx_geo_return_local']*100:.2f}%**
- Combined geometric return in {diag['output_currency']}: **{diag['combined_geo_return_local']*100:.2f}%**
- Net uplift vs USD view: **{uplift*100:.2f}% per year**
            """
        )


def annual_rate_to_monthly_rate(annual_rate: float) -> float:
    if annual_rate <= -1.0:
        raise ValueError("Annual rate must be greater than -100%.")
    return (1.0 + annual_rate) ** (1.0 / 12.0) - 1.0


def make_contribution_schedule(
    months: int,
    monthly_contribution: float,
    contribution_growth_mode: str = "fixed",
    contribution_growth_annual: float = 0.0,
    monthly_inflation: np.ndarray | None = None,
) -> np.ndarray:
    """Return the nominal contribution made in each simulated month.

    fixed  = same cash amount every month.
    custom = contribution rises by the selected annual growth rate.
    cpi    = contribution rises with the realised CPI path where available,
             otherwise it falls back to the custom annual growth rate.
    """
    months = int(months)
    if months <= 0:
        return np.array([], dtype=float)

    base = max(0.0, float(monthly_contribution))
    if base == 0.0:
        return np.zeros(months, dtype=float)

    mode = str(contribution_growth_mode or "fixed")
    if mode == "fixed":
        return np.full(months, base, dtype=float)

    contrib = np.empty(months, dtype=float)
    contrib[0] = base

    if mode == "cpi" and monthly_inflation is not None:
        infl = np.asarray(monthly_inflation, dtype=float)
        if len(infl) >= months and np.isfinite(infl[:months]).all():
            for i in range(1, months):
                contrib[i] = contrib[i - 1] * max(0.0, 1.0 + float(infl[i - 1]))
            return contrib

    monthly_growth = annual_rate_to_monthly_rate(float(contribution_growth_annual))
    for i in range(1, months):
        contrib[i] = contrib[i - 1] * (1.0 + monthly_growth)
    return contrib


def annualised_geometric_return(returns: pd.Series | np.ndarray) -> float:
    arr = np.asarray(returns, dtype=float)
    arr = arr[np.isfinite(arr)]
    if len(arr) == 0 or np.any(1.0 + arr <= 0):
        return float("nan")
    return float(np.prod(1.0 + arr) ** (12.0 / len(arr)) - 1.0)


def real_to_nominal_return(real_return: float, inflation_rate: float) -> float:
    """Convert an annual real return into an annual nominal return.

    CAPE/Shiller-style valuation forecasts are best interpreted as real,
    inflation-adjusted return anchors. The simulation engine projects nominal
    account balances, so CAPE-mode forecasts add expected inflation back before
    shifting Monte Carlo path returns.
    """
    if not np.isfinite(real_return):
        return float("nan")
    if not np.isfinite(inflation_rate):
        inflation_rate = 0.0
    return float((1.0 + float(real_return)) * (1.0 + float(inflation_rate)) - 1.0)


def annualised_real_geometric_return(returns_df: pd.DataFrame) -> float:
    """Annualised real return using monthly nominal returns and CPI inflation."""
    if "return" not in returns_df.columns or "monthly_inflation" not in returns_df.columns:
        return annualised_geometric_return(returns_df.get("return", pd.Series(dtype=float)))
    nominal = pd.to_numeric(returns_df["return"], errors="coerce")
    inflation = pd.to_numeric(returns_df["monthly_inflation"], errors="coerce")
    valid = nominal.notna() & inflation.notna() & ((1.0 + inflation) > 0)
    if not valid.any():
        return annualised_geometric_return(nominal)
    real_monthly = (1.0 + nominal.loc[valid]) / (1.0 + inflation.loc[valid]) - 1.0
    return annualised_geometric_return(real_monthly)


def get_latest_cape_value(returns_df: pd.DataFrame) -> float:
    if "cape" not in returns_df.columns:
        return float("nan")
    valid = pd.to_numeric(returns_df["cape"], errors="coerce").dropna()
    if valid.empty:
        return float("nan")
    return float(valid.iloc[-1])


def cape_similarity_weights(
    returns_df: pd.DataFrame,
    current_cape: float,
    strength: float = 1.0,
    min_weight_fraction: float = 0.03,
) -> np.ndarray:
    """Return month-level sampling weights based on similarity to current CAPE.

    Higher strength makes the bootstrap focus more tightly on historical months
    whose starting CAPE was similar to today's/latest CAPE. A small floor keeps
    other valuation regimes possible so the model does not overfit one cluster.
    """
    n = len(returns_df)
    if n == 0:
        return np.array([], dtype=float)
    if "cape" not in returns_df.columns or not np.isfinite(current_cape):
        return np.full(n, 1.0 / n, dtype=float)

    cape = pd.to_numeric(returns_df["cape"], errors="coerce").to_numpy(dtype=float)
    valid = np.isfinite(cape)
    if not valid.any():
        return np.full(n, 1.0 / n, dtype=float)

    cape_std = float(np.nanstd(cape[valid]))
    if not np.isfinite(cape_std) or cape_std <= 0:
        return np.full(n, 1.0 / n, dtype=float)

    distance = np.abs(cape - float(current_cape)) / cape_std
    raw = np.exp(-float(strength) * distance)
    raw = np.where(valid, raw, 0.0)

    if np.nanmax(raw) > 0:
        floor = float(min_weight_fraction) * float(np.nanmax(raw))
        raw = np.where(valid, np.maximum(raw, floor), 0.0)

    if raw.sum() <= 0 or not np.isfinite(raw.sum()):
        return np.full(n, 1.0 / n, dtype=float)
    return raw / raw.sum()


def block_start_weights_from_month_weights(month_weights: np.ndarray, block_months: int, max_start: int) -> np.ndarray:
    """Convert month weights to valid block-start weights."""
    w = np.asarray(month_weights, dtype=float)
    if max_start <= 0:
        return np.array([], dtype=float)
    if len(w) < max_start:
        return np.full(max_start, 1.0 / max_start, dtype=float)
    start_weights = np.asarray(w[:max_start], dtype=float)
    if start_weights.sum() <= 0 or not np.isfinite(start_weights.sum()):
        return np.full(max_start, 1.0 / max_start, dtype=float)
    return start_weights / start_weights.sum()


def valuation_adjusted_expected_return(
    historical_geo_return: float,
    current_cape: float,
    fair_cape: float,
    cape_sensitivity: float,
) -> float:
    """Simple valuation anchor: high CAPE reduces the forward return assumption.

    This is intentionally transparent rather than over-fitted. Example: if
    current CAPE is above the fair/long-run CAPE, the expected annual return is
    reduced by sensitivity × log(current/fair).
    """
    if not np.isfinite(historical_geo_return):
        historical_geo_return = 0.07
    if current_cape <= 0 or fair_cape <= 0 or cape_sensitivity == 0:
        return float(historical_geo_return)
    adj = float(cape_sensitivity) * float(np.log(current_cape / fair_cape))
    return float(np.clip(historical_geo_return - adj, -0.50, 0.50))


def shift_returns_to_target_annual_return(path_returns: np.ndarray, target_annual_return: float) -> np.ndarray:
    """Shift monthly log returns so the path's annualised return matches an anchor.

    This preserves the sequence shape and volatility clusters while making the
    Monte Carlo path consistent with a forward-looking expected-return view.
    """
    arr = np.asarray(path_returns, dtype=float)
    if not np.isfinite(target_annual_return) or target_annual_return <= -0.95:
        return arr
    gross = 1.0 + arr
    if len(arr) == 0 or np.any(gross <= 0) or not np.isfinite(gross).all():
        return arr
    target_monthly_log = np.log1p(float(target_annual_return)) / 12.0
    current_monthly_log = float(np.mean(np.log(gross)))
    shifted = np.exp(np.log(gross) + (target_monthly_log - current_monthly_log)) - 1.0
    return np.clip(shifted, -0.95, 5.0)


def filter_monte_carlo_sample_pool(returns_df: pd.DataFrame, sample_pool_mode: str) -> pd.DataFrame:
    """Apply an optional conditional sample pool for Monte Carlo.

    The selected study start still controls the base sample. These modes then
    narrow the bootstrap pool to periods that better represent the desired
    forecast condition.
    """
    mode = str(sample_pool_mode or "active")
    data = returns_df.copy().reset_index(drop=True)
    if mode == "modern_1990":
        data = data.loc[data["date"] >= pd.Timestamp(1990, 1, 1)]
    elif mode == "post_1973":
        data = data.loc[data["date"] >= pd.Timestamp(1973, 1, 1)]
    elif mode == "high_inflation":
        if "cpi_annual_pct" in data.columns:
            data = data.loc[pd.to_numeric(data["cpi_annual_pct"], errors="coerce") >= 5.0]
    elif mode == "crisis":
        trailing_12m = (1.0 + data["return"].astype(float)).rolling(12).apply(np.prod, raw=True) - 1.0
        data = data.loc[(trailing_12m <= 0.0) | (data["return"].astype(float) <= -0.05)]
    return data.reset_index(drop=True)


def apply_period_fee(portfolio_value: float, fund_fee_annual: float, platform_fee_annual: float, platform_fee_monthly_min: float, platform_fee_annual_cap: float) -> tuple[float, float]:
    if portfolio_value <= 0:
        return 0.0, 0.0
    fund_fee = portfolio_value * annual_rate_to_monthly_rate(fund_fee_annual)
    platform_fee_raw = portfolio_value * annual_rate_to_monthly_rate(platform_fee_annual)
    if platform_fee_annual_cap > 0:
        platform_fee_raw = min(platform_fee_raw, platform_fee_annual_cap / 12.0)
    platform_fee = max(platform_fee_raw, platform_fee_monthly_min) if platform_fee_monthly_min > 0 else platform_fee_raw
    total_fee = max(0.0, fund_fee + platform_fee)
    return max(0.0, portfolio_value - total_fee), total_fee


def max_consecutive_true(values: pd.Series | np.ndarray) -> int:
    best = current = 0
    for val in pd.Series(values).fillna(False).astype(bool):
        if val:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def cashflow_irr_from_final_value(
    final_value: float,
    years: int,
    initial_investment: float,
    monthly_contribution: float,
    contribution_timing: str,
    contribution_growth_mode: str = "fixed",
    contribution_growth_annual: float = 0.0,
    monthly_inflation: np.ndarray | None = None,
) -> float:
    """Estimate annual money-weighted return from regular monthly cashflows."""
    months = int(years * 12)
    if months <= 0 or not np.isfinite(final_value) or final_value <= 0:
        return float("nan")

    contributions = make_contribution_schedule(
        months,
        monthly_contribution,
        contribution_growth_mode,
        contribution_growth_annual,
        monthly_inflation,
    )
    initial_investment = float(initial_investment)

    if contribution_timing == "start":
        first = contributions[0] if len(contributions) else 0.0
        flows = [-(initial_investment + first)]
        flows.extend([-float(x) for x in contributions[1:]])
        flows.append(float(final_value))
    else:
        last = contributions[-1] if len(contributions) else 0.0
        flows = [-initial_investment]
        flows.extend([-float(x) for x in contributions[:-1]])
        flows.append(float(final_value) - float(last))

    if not any(f < 0 for f in flows) or not any(f > 0 for f in flows):
        return float("nan")

    def npv_from_annual_rate(annual_rate: float) -> float:
        if annual_rate <= -1.0:
            return float("inf")
        monthly_discount = (1.0 + annual_rate) ** (1.0 / 12.0)
        if not np.isfinite(monthly_discount) or monthly_discount <= 0.0:
            return float("nan")

        acc = 0.0
        for cf in reversed(flows):
            acc = cf + acc / monthly_discount
            if not np.isfinite(acc):
                return float("inf") if acc > 0 else float("-inf")
        return float(acc)

    low, high = -0.999, 1.0
    npv_low, npv_high = npv_from_annual_rate(low), npv_from_annual_rate(high)

    for _ in range(30):
        if np.isfinite(npv_low) and np.isfinite(npv_high) and npv_low * npv_high <= 0:
            break
        high *= 2.0
        if high > 1000.0:
            return float("nan")
        npv_high = npv_from_annual_rate(high)
    else:
        return float("nan")

    for _ in range(80):
        mid = (low + high) / 2.0
        npv_mid = npv_from_annual_rate(mid)
        if not np.isfinite(npv_mid):
            low = mid
            continue
        if abs(npv_mid) < 1e-7:
            return float(mid)
        if npv_low * npv_mid <= 0:
            high = mid
            npv_high = npv_mid
        else:
            low = mid
            npv_low = npv_mid

    return float((low + high) / 2.0)

def summarise_distribution(final_values: pd.Series, real_final_values: pd.Series, start_dates: pd.Series, end_dates: pd.Series, total_contribution: float, years: int, initial_investment: float, monthly_contribution: float, contribution_timing: str, total_fees: pd.Series, max_drawdowns: pd.Series, target_wealth: float, contribution_growth_mode: str = "fixed", contribution_growth_annual: float = 0.0) -> pd.Series:
    if final_values.empty:
        raise ValueError("No valid rolling windows were available for this horizon and filter combination.")

    if isinstance(total_contribution, (pd.Series, np.ndarray, list, tuple)):
        total_contribution_s = pd.Series(total_contribution, index=final_values.index, dtype="float64")
        typical_total_contribution = float(total_contribution_s.median()) if total_contribution_s.notna().any() else float("nan")
    else:
        typical_total_contribution = float(total_contribution)
        total_contribution_s = pd.Series(typical_total_contribution, index=final_values.index, dtype="float64")
    wealth_multiple = final_values / total_contribution_s.replace(0, np.nan)
    paid_in_annualised = wealth_multiple ** (1 / years) - 1
    real_values = pd.Series(real_final_values, dtype="float64")
    real_count = int(real_values.notna().sum())
    real_coverage_share = float(real_values.notna().mean()) if len(real_values) else float("nan")

    worst_idx = final_values.idxmin()
    best_idx = final_values.idxmax()
    median_final = float(final_values.median())
    p10_final = float(final_values.quantile(0.10))
    p90_final = float(final_values.quantile(0.90))

    return pd.Series({
        "count": int(final_values.count()),
        "real_count": real_count,
        "cpi_coverage_share": real_coverage_share,
        "total_contribution": typical_total_contribution,
        "min": float(final_values.min()),
        "p05": float(final_values.quantile(0.05)),
        "p10": p10_final,
        "median": median_final,
        "mean": float(final_values.mean()),
        "p90": p90_final,
        "p95": float(final_values.quantile(0.95)),
        "max": float(final_values.max()),
        "std": float(final_values.std(ddof=1)),
        "real_p10": float(real_values.quantile(0.10)) if real_count else float("nan"),
        "real_median": float(real_values.median()) if real_count else float("nan"),
        "real_p90": float(real_values.quantile(0.90)) if real_count else float("nan"),
        "wealth_multiple_median": float(wealth_multiple.median()),
        "paid_in_annualised_median": float(paid_in_annualised.median()),
        "mwr_p10": cashflow_irr_from_final_value(p10_final, years, initial_investment, monthly_contribution, contribution_timing, contribution_growth_mode, contribution_growth_annual),
        "mwr_median": cashflow_irr_from_final_value(median_final, years, initial_investment, monthly_contribution, contribution_timing, contribution_growth_mode, contribution_growth_annual),
        "mwr_p90": cashflow_irr_from_final_value(p90_final, years, initial_investment, monthly_contribution, contribution_timing, contribution_growth_mode, contribution_growth_annual),
        "prob_below_contribution": float((final_values < total_contribution_s).mean()) if total_contribution_s.notna().any() else float("nan"),
        "prob_above_target": float((final_values >= target_wealth).mean()) if target_wealth > 0 else float("nan"),
        "fees_median": float(total_fees.median()),
        "fees_mean": float(total_fees.mean()),
        "max_drawdown_median": float(max_drawdowns.median()),
        "max_drawdown_worst": float(max_drawdowns.min()),
        "worst_start": start_dates.loc[worst_idx],
        "worst_end": end_dates.loc[worst_idx],
        "best_start": start_dates.loc[best_idx],
        "best_end": end_dates.loc[best_idx],
    })


def simulate_rolling_horizon(returns_df: pd.DataFrame, years: int, initial_investment: float, monthly_contribution: float, fund_fee_annual: float, platform_fee_annual: float, platform_fee_monthly_min: float, platform_fee_annual_cap: float, contribution_timing: str, only_full_fx_windows: bool, target_wealth: float, contribution_growth_mode: str = "fixed", contribution_growth_annual: float = 0.0, extra_tracking_drag_annual: float = 0.0) -> HistoricalSimulationResult:
    months = years * 12
    n = len(returns_df)
    if n < months:
        raise ValueError(f"Dataset has {n} rows, but needs at least {months} rows for a {years}-year rolling study.")

    final_values, real_final_values, start_dates, end_dates, total_fees_all, max_drawdowns_all, total_contributions_all = [], [], [], [], [], [], []
    returns = returns_df["return"].to_numpy(dtype=float)
    fx_covered = returns_df.get("fx_covered", pd.Series(True, index=returns_df.index)).to_numpy(dtype=bool)
    monthly_inflation = returns_df.get("monthly_inflation", pd.Series(np.nan, index=returns_df.index)).to_numpy(dtype=float)
    dates = returns_df["date"].reset_index(drop=True)

    for start_idx in range(0, n - months + 1):
        end_idx = start_idx + months
        if only_full_fx_windows and not bool(fx_covered[start_idx:end_idx].all()):
            continue

        portfolio = float(initial_investment)
        total_fees_paid = 0.0
        peak = max(portfolio, 1e-12)
        max_dd = 0.0

        window_inflation = monthly_inflation[start_idx:end_idx]
        contribution_schedule = make_contribution_schedule(
            months,
            monthly_contribution,
            contribution_growth_mode,
            contribution_growth_annual,
            window_inflation,
        )

        for local_i, t in enumerate(range(start_idx, end_idx)):
            contribution = float(contribution_schedule[local_i])
            if contribution_timing == "start":
                portfolio += contribution
                portfolio *= (1.0 + returns[t])
                portfolio, fee_paid = apply_period_fee(portfolio, fund_fee_annual + extra_tracking_drag_annual, platform_fee_annual, platform_fee_monthly_min, platform_fee_annual_cap)
            else:
                portfolio *= (1.0 + returns[t])
                portfolio, fee_paid = apply_period_fee(portfolio, fund_fee_annual + extra_tracking_drag_annual, platform_fee_annual, platform_fee_monthly_min, platform_fee_annual_cap)
                portfolio += contribution
            total_fees_paid += fee_paid
            peak = max(peak, portfolio, 1e-12)
            max_dd = min(max_dd, (portfolio / peak) - 1.0)

        inflation_factor = cumulative_inflation_factor(window_inflation)
        real_portfolio = portfolio / inflation_factor if np.isfinite(inflation_factor) and inflation_factor > 0 else float("nan")

        final_values.append(portfolio)
        real_final_values.append(real_portfolio)
        start_dates.append(dates.iloc[start_idx])
        end_dates.append(dates.iloc[end_idx - 1])
        total_fees_all.append(total_fees_paid)
        max_drawdowns_all.append(max_dd)
        total_contributions_all.append(float(initial_investment) + float(contribution_schedule.sum()))

    if not final_values:
        raise ValueError(f"No valid {years}-year rolling windows after applying the FX coverage filter. Reduce the horizon, switch currency, or disable the full-FX-coverage filter.")

    final_values_s = pd.Series(final_values, name="final_value")
    real_final_values_s = pd.Series(real_final_values, name="real_final_value")
    start_dates_s = pd.Series(start_dates, name="start_date")
    end_dates_s = pd.Series(end_dates, name="end_date")
    total_fees_s = pd.Series(total_fees_all, name="total_fees")
    max_drawdowns_s = pd.Series(max_drawdowns_all, name="max_drawdown")
    total_contributions_s = pd.Series(total_contributions_all, name="total_contribution")
    total_contribution = float(total_contributions_s.median())

    stats = summarise_distribution(final_values_s, real_final_values_s, start_dates_s, end_dates_s, total_contributions_s, years, initial_investment, monthly_contribution, contribution_timing, total_fees_s, max_drawdowns_s, target_wealth, contribution_growth_mode, contribution_growth_annual)
    return HistoricalSimulationResult(years, float(total_contribution), start_dates_s, end_dates_s, final_values_s, real_final_values_s, total_fees_s, max_drawdowns_s, stats)


def simulate_path_from_returns(
    path_returns: np.ndarray,
    initial_investment: float,
    monthly_contribution: float,
    fund_fee_annual: float,
    platform_fee_annual: float,
    platform_fee_monthly_min: float,
    platform_fee_annual_cap: float,
    contribution_timing: str,
    contribution_growth_mode: str = "fixed",
    contribution_growth_annual: float = 0.0,
    monthly_inflation: np.ndarray | None = None,
    extra_tracking_drag_annual: float = 0.0,
) -> tuple[float, float, float, float]:
    """Run one portfolio path and return final value, total fees, max drawdown and total paid in."""
    path_returns = np.asarray(path_returns, dtype=float)
    contribution_schedule = make_contribution_schedule(
        len(path_returns),
        monthly_contribution,
        contribution_growth_mode,
        contribution_growth_annual,
        monthly_inflation,
    )
    portfolio = float(initial_investment)
    total_fees_paid = 0.0
    peak = max(portfolio, 1e-12)
    max_dd = 0.0

    for i, ret in enumerate(path_returns):
        contribution = float(contribution_schedule[i])
        if contribution_timing == "start":
            portfolio += contribution
            portfolio *= (1.0 + float(ret))
            portfolio, fee_paid = apply_period_fee(
                portfolio,
                fund_fee_annual + extra_tracking_drag_annual,
                platform_fee_annual,
                platform_fee_monthly_min,
                platform_fee_annual_cap,
            )
        else:
            portfolio *= (1.0 + float(ret))
            portfolio, fee_paid = apply_period_fee(
                portfolio,
                fund_fee_annual + extra_tracking_drag_annual,
                platform_fee_annual,
                platform_fee_monthly_min,
                platform_fee_annual_cap,
            )
            portfolio += contribution

        total_fees_paid += fee_paid
        peak = max(peak, portfolio, 1e-12)
        max_dd = min(max_dd, (portfolio / peak) - 1.0)

    total_paid_in = float(initial_investment) + float(contribution_schedule.sum())
    return float(portfolio), float(total_fees_paid), float(max_dd), total_paid_in

def summarise_monte_carlo_distribution(
    final_values: pd.Series,
    real_final_values: pd.Series,
    total_contribution: float,
    years: int,
    initial_investment: float,
    monthly_contribution: float,
    contribution_timing: str,
    total_fees: pd.Series,
    max_drawdowns: pd.Series,
    target_wealth: float,
    contribution_growth_mode: str = "fixed",
    contribution_growth_annual: float = 0.0,
) -> pd.Series:
    if final_values.empty:
        raise ValueError("No Monte Carlo paths were generated.")

    if isinstance(total_contribution, (pd.Series, np.ndarray, list, tuple)):
        total_contribution_s = pd.Series(total_contribution, index=final_values.index, dtype="float64")
        typical_total_contribution = float(total_contribution_s.median()) if total_contribution_s.notna().any() else float("nan")
    else:
        typical_total_contribution = float(total_contribution)
        total_contribution_s = pd.Series(typical_total_contribution, index=final_values.index, dtype="float64")
    wealth_multiple = final_values / total_contribution_s.replace(0, np.nan)
    paid_in_annualised = wealth_multiple ** (1 / years) - 1
    real_values = pd.Series(real_final_values, dtype="float64")
    real_count = int(real_values.notna().sum())
    real_coverage_share = float(real_values.notna().mean()) if len(real_values) else float("nan")

    median_final = float(final_values.median())
    p10_final = float(final_values.quantile(0.10))
    p90_final = float(final_values.quantile(0.90))

    return pd.Series({
        "count": int(final_values.count()),
        "real_count": real_count,
        "cpi_coverage_share": real_coverage_share,
        "total_contribution": typical_total_contribution,
        "min": float(final_values.min()),
        "p05": float(final_values.quantile(0.05)),
        "p10": p10_final,
        "median": median_final,
        "mean": float(final_values.mean()),
        "p90": p90_final,
        "p95": float(final_values.quantile(0.95)),
        "max": float(final_values.max()),
        "std": float(final_values.std(ddof=1)),
        "real_p10": float(real_values.quantile(0.10)) if real_count else float("nan"),
        "real_median": float(real_values.median()) if real_count else float("nan"),
        "real_p90": float(real_values.quantile(0.90)) if real_count else float("nan"),
        "wealth_multiple_median": float(wealth_multiple.median()),
        "paid_in_annualised_median": float(paid_in_annualised.median()),
        "mwr_p10": cashflow_irr_from_final_value(p10_final, years, initial_investment, monthly_contribution, contribution_timing, contribution_growth_mode, contribution_growth_annual),
        "mwr_median": cashflow_irr_from_final_value(median_final, years, initial_investment, monthly_contribution, contribution_timing, contribution_growth_mode, contribution_growth_annual),
        "mwr_p90": cashflow_irr_from_final_value(p90_final, years, initial_investment, monthly_contribution, contribution_timing, contribution_growth_mode, contribution_growth_annual),
        "prob_below_contribution": float((final_values < total_contribution_s).mean()) if total_contribution_s.notna().any() else float("nan"),
        "prob_above_target": float((final_values >= target_wealth).mean()) if target_wealth > 0 else float("nan"),
        "fees_median": float(total_fees.median()),
        "fees_mean": float(total_fees.mean()),
        "max_drawdown_median": float(max_drawdowns.median()),
        "max_drawdown_worst": float(max_drawdowns.min()),
    })


def simulate_monte_carlo_block_bootstrap(
    returns_df: pd.DataFrame,
    years: int,
    initial_investment: float,
    monthly_contribution: float,
    fund_fee_annual: float,
    platform_fee_annual: float,
    platform_fee_monthly_min: float,
    platform_fee_annual_cap: float,
    contribution_timing: str,
    only_full_fx_windows: bool,
    target_wealth: float,
    n_simulations: int,
    block_months: int,
    random_seed: int,
    sample_pool_mode: str = "active",
    forecast_mode: str = "historical",
    target_return_annual: float | None = None,
    contribution_growth_mode: str = "fixed",
    contribution_growth_annual: float = 0.0,
    extra_tracking_drag_annual: float = 0.0,
    cape_matching_strength: float = 1.0,
) -> MonteCarloSimulationResult:
    """Block-bootstrap Monte Carlo using historical monthly returns and matching CPI months where available."""
    months = int(years * 12)
    n_simulations = int(n_simulations)
    block_months = int(block_months)

    if months <= 0:
        raise ValueError("Monte Carlo horizon must be positive.")
    if n_simulations < 10:
        raise ValueError("Use at least 10 Monte Carlo paths.")
    if block_months < 1:
        raise ValueError("Block length must be at least 1 month.")

    data = returns_df.copy().reset_index(drop=True)
    if only_full_fx_windows:
        data = data.loc[data.get("fx_covered", pd.Series(True, index=data.index)).astype(bool)].reset_index(drop=True)

    data = filter_monte_carlo_sample_pool(data, sample_pool_mode)
    data = data.dropna(subset=["return"]).reset_index(drop=True)
    available_returns = data["return"].to_numpy(dtype=float)
    available_inflation = data.get("monthly_inflation", pd.Series(np.nan, index=data.index)).to_numpy(dtype=float)
    n = len(available_returns)
    if n < block_months:
        raise ValueError(
            f"Not enough monthly returns for a {block_months}-month bootstrap block after filters. "
            "Reduce the block length, choose a broader Monte Carlo sample pool, disable full-FX coverage, or choose a longer sample."
        )

    rng = np.random.default_rng(int(random_seed))
    max_start = n - block_months + 1

    block_start_probabilities = None
    if sample_pool_mode == "cape_conditioned":
        current_cape = get_latest_cape_value(data)
        month_weights = cape_similarity_weights(
            data,
            current_cape=current_cape,
            strength=float(cape_matching_strength),
        )
        block_start_probabilities = block_start_weights_from_month_weights(month_weights, block_months, max_start)

    final_values, real_final_values, total_fees_all, max_drawdowns_all, total_contributions_all = [], [], [], [], []

    for _ in range(n_simulations):
        sampled_returns = []
        sampled_inflation = []
        while len(sampled_returns) < months:
            if block_start_probabilities is None:
                start = int(rng.integers(0, max_start))
            else:
                start = int(rng.choice(np.arange(max_start), p=block_start_probabilities))
            sampled_returns.extend(available_returns[start:start + block_months])
            sampled_inflation.extend(available_inflation[start:start + block_months])
        path_returns = np.asarray(sampled_returns[:months], dtype=float)
        path_inflation = np.asarray(sampled_inflation[:months], dtype=float)

        if forecast_mode in {"forward", "cape"} and target_return_annual is not None and np.isfinite(target_return_annual):
            path_returns = shift_returns_to_target_annual_return(path_returns, float(target_return_annual))

        final_value, fees_paid, max_dd, total_paid_in = simulate_path_from_returns(
            path_returns,
            initial_investment,
            monthly_contribution,
            fund_fee_annual,
            platform_fee_annual,
            platform_fee_monthly_min,
            platform_fee_annual_cap,
            contribution_timing,
            contribution_growth_mode,
            contribution_growth_annual,
            path_inflation,
            extra_tracking_drag_annual,
        )
        inflation_factor = cumulative_inflation_factor(path_inflation)
        real_value = final_value / inflation_factor if np.isfinite(inflation_factor) and inflation_factor > 0 else float("nan")
        final_values.append(final_value)
        real_final_values.append(real_value)
        total_fees_all.append(fees_paid)
        max_drawdowns_all.append(max_dd)
        total_contributions_all.append(total_paid_in)

    final_values_s = pd.Series(final_values, name="final_value")
    real_final_values_s = pd.Series(real_final_values, name="real_final_value")
    total_fees_s = pd.Series(total_fees_all, name="total_fees")
    max_drawdowns_s = pd.Series(max_drawdowns_all, name="max_drawdown")
    total_contributions_s = pd.Series(total_contributions_all, name="total_contribution")
    total_contribution = float(total_contributions_s.median())
    stats = summarise_monte_carlo_distribution(
        final_values_s,
        real_final_values_s,
        total_contributions_s,
        years,
        initial_investment,
        monthly_contribution,
        contribution_timing,
        total_fees_s,
        max_drawdowns_s,
        target_wealth,
        contribution_growth_mode,
        contribution_growth_annual,
    )
    return MonteCarloSimulationResult(
        years=years,
        total_contribution=float(total_contribution),
        final_values=final_values_s,
        real_final_values=real_final_values_s,
        total_fees=total_fees_s,
        max_drawdowns=max_drawdowns_s,
        stats=stats,
        simulations=n_simulations,
        block_months=block_months,
    )


def simulate_realised_future_path(
    future_df: pd.DataFrame,
    initial_investment: float,
    monthly_contribution: float,
    fund_fee_annual: float,
    platform_fee_annual: float,
    platform_fee_monthly_min: float,
    platform_fee_annual_cap: float,
    contribution_timing: str,
    contribution_growth_mode: str,
    contribution_growth_annual: float,
    extra_tracking_drag_annual: float,
) -> float:
    """Simulate the actually realised future path for calibration testing."""
    returns = future_df["return"].to_numpy(dtype=float)
    inflation = future_df.get("monthly_inflation", pd.Series(np.nan, index=future_df.index)).to_numpy(dtype=float)
    final_value, _, _, _ = simulate_path_from_returns(
        returns,
        initial_investment,
        monthly_contribution,
        fund_fee_annual,
        platform_fee_annual,
        platform_fee_monthly_min,
        platform_fee_annual_cap,
        contribution_timing,
        contribution_growth_mode,
        contribution_growth_annual,
        inflation,
        extra_tracking_drag_annual,
    )
    return float(final_value)


def run_forecast_calibration(
    full_df: pd.DataFrame,
    horizon_years: int,
    initial_investment: float,
    monthly_contribution: float,
    fund_fee_annual: float,
    platform_fee_annual: float,
    platform_fee_monthly_min: float,
    platform_fee_annual_cap: float,
    contribution_timing: str,
    only_full_fx_windows: bool,
    target_wealth: float,
    n_paths: int,
    block_months: int,
    random_seed: int,
    sample_pool_mode: str,
    forecast_mode: str,
    forward_expected_return_annual: float | None,
    contribution_growth_mode: str,
    contribution_growth_annual: float,
    extra_tracking_drag_annual: float,
    cape_matching_strength: float,
    fair_cape: float,
    cape_sensitivity: float,
    expected_inflation_annual: float = 0.025,
    start_year: int = 1950,
    step_years: int = 5,
) -> pd.DataFrame:
    """Out-of-sample calibration: forecast from past dates, then compare with realised future paths."""
    months = int(horizon_years * 12)
    if months <= 0:
        raise ValueError("Calibration horizon must be positive.")
    data = full_df.copy().sort_values("date").reset_index(drop=True)
    if only_full_fx_windows:
        data = data.loc[data.get("fx_covered", pd.Series(True, index=data.index)).astype(bool)].reset_index(drop=True)

    last_forecast_date = data["date"].max() - pd.DateOffset(months=months)
    if last_forecast_date < pd.Timestamp(start_year, 1, 31):
        raise ValueError("Not enough data remains for the selected calibration horizon and start year.")

    calibration_dates = pd.date_range(
        start=pd.Timestamp(start_year, 12, 31),
        end=last_forecast_date,
        freq=f"{int(step_years)}YE",
    )

    results: list[dict] = []
    rng_master = np.random.default_rng(int(random_seed))

    for forecast_date in calibration_dates:
        train_df = data.loc[data["date"] <= forecast_date].copy().reset_index(drop=True)
        future_df = data.loc[(data["date"] > forecast_date) & (data["date"] <= forecast_date + pd.DateOffset(months=months))].copy().reset_index(drop=True)

        if len(train_df) < max(months, block_months + 1) or len(future_df) < months:
            continue

        target_return_for_test = None
        if forecast_mode == "forward":
            target_return_for_test = forward_expected_return_annual
        elif forecast_mode == "cape":
            train_real_geo = annualised_real_geometric_return(train_df)
            train_cape = get_latest_cape_value(train_df)
            target_real_return = valuation_adjusted_expected_return(train_real_geo, train_cape, fair_cape, cape_sensitivity)
            target_return_for_test = real_to_nominal_return(target_real_return, expected_inflation_annual)

        seed = int(rng_master.integers(0, 1_000_000_000))
        mc = simulate_monte_carlo_block_bootstrap(
            train_df,
            horizon_years,
            initial_investment,
            monthly_contribution,
            fund_fee_annual,
            platform_fee_annual,
            platform_fee_monthly_min,
            platform_fee_annual_cap,
            contribution_timing,
            False,
            target_wealth,
            int(n_paths),
            int(block_months),
            seed,
            sample_pool_mode,
            forecast_mode,
            target_return_for_test if forecast_mode in {"forward", "cape"} else None,
            contribution_growth_mode,
            contribution_growth_annual,
            extra_tracking_drag_annual,
            cape_matching_strength,
        )

        actual_final = simulate_realised_future_path(
            future_df.iloc[:months].copy(),
            initial_investment,
            monthly_contribution,
            fund_fee_annual,
            platform_fee_annual,
            platform_fee_monthly_min,
            platform_fee_annual_cap,
            contribution_timing,
            contribution_growth_mode,
            contribution_growth_annual,
            extra_tracking_drag_annual,
        )

        p10 = float(mc.final_values.quantile(0.10))
        p50 = float(mc.final_values.median())
        p90 = float(mc.final_values.quantile(0.90))
        target_share = float((mc.final_values >= target_wealth).mean()) if target_wealth > 0 else float("nan")

        results.append({
            "forecast_date": forecast_date,
            "horizon_years": int(horizon_years),
            "train_start": train_df["date"].min(),
            "train_end": train_df["date"].max(),
            "actual_end": future_df.iloc[months - 1]["date"],
            "cape_at_forecast": get_latest_cape_value(train_df),
            "forecast_p10": p10,
            "forecast_median": p50,
            "forecast_p90": p90,
            "actual_final": actual_final,
            "inside_10_90_band": bool(p10 <= actual_final <= p90),
            "actual_above_median": bool(actual_final >= p50),
            "actual_vs_median_pct": float(actual_final / p50 - 1.0) if p50 > 0 else float("nan"),
            "target_model_share": target_share,
        })

    return pd.DataFrame(results)


def summarise_calibration(calibration_df: pd.DataFrame) -> pd.Series:
    if calibration_df.empty:
        return pd.Series({
            "tests": 0,
            "p10_p90_coverage": float("nan"),
            "actual_above_median_rate": float("nan"),
            "median_bias": float("nan"),
        })
    return pd.Series({
        "tests": int(len(calibration_df)),
        "p10_p90_coverage": float(calibration_df["inside_10_90_band"].mean()),
        "actual_above_median_rate": float(calibration_df["actual_above_median"].mean()),
        "median_bias": float(calibration_df["actual_vs_median_pct"].median()),
    })

def fmt_currency(value: float, currency_symbol: str) -> str:
    if pd.isna(value):
        return "n/a"
    return f"{currency_symbol}{value:,.0f}"


def fmt_percent(value: float) -> str:
    if pd.isna(value):
        return "n/a"
    return f"{value * 100:.2f}%"


def fmt_multiple(value: float) -> str:
    if pd.isna(value):
        return "n/a"
    return f"{value:.2f}x"


def fmt_date(value: object) -> str:
    if pd.isna(value):
        return "n/a"
    return pd.to_datetime(value).strftime("%Y-%m")


def _metric_card(label: str, value: str, note: str = "", wide: bool = False) -> str:
    wide_class = " kpi-wide" if wide else ""
    return (
        f'<div class="kpi-card{wide_class}">'
        f'<div class="kpi-label">{label}</div>'
        f'<div class="kpi-value">{value}</div>'
        f'<div class="kpi-note">{note}</div>'
        '</div>'
    )


def _mini_card(label: str, value: str) -> str:
    return (
        '<div class="mini-card">'
        f'<div class="mini-label">{label}</div>'
        f'<div class="mini-value">{value}</div>'
        '</div>'
    )


def render_metric_cards(stats: pd.Series, currency_symbol: str, target_wealth: float) -> None:
    range_value = f"{fmt_currency(stats['p10'], currency_symbol)} → {fmt_currency(stats['p90'], currency_symbol)}"
    third_label = "Median CPI-adjusted"
    third_value = fmt_currency(stats.get("real_median", float("nan")), currency_symbol)
    fifth_label = "Historical windows above target" if target_wealth > 0 else "Historical windows below paid-in"
    fifth_value = fmt_percent(stats["prob_above_target"]) if target_wealth > 0 else fmt_percent(stats["prob_below_contribution"])

    html = "".join([
        _metric_card("Median ending wealth", fmt_currency(stats["median"], currency_symbol), "Middle historical rolling outcome."),
        _metric_card("10th → 90th range", range_value, "Central historical outcome band.", wide=True),
        _metric_card(third_label, third_value, f"Historical CPI where covered · {int(stats.get('real_count', 0)):,} windows."),
        _metric_card("Median MWR", fmt_percent(stats["mwr_median"]), "Money-weighted annual return estimate."),
        _metric_card(fifth_label, fifth_value, "Share of historical rolling windows."),
    ])
    st.markdown(f'<div class="kpi-grid">{html}</div>', unsafe_allow_html=True)

    mini_html = "".join([
        _mini_card("Historical windows", f"{int(stats['count']):,}"),
        _mini_card("Paid in", fmt_currency(stats["total_contribution"], currency_symbol)),
        _mini_card("Median fees", fmt_currency(stats["fees_median"], currency_symbol)),
        _mini_card("Median max drawdown", fmt_percent(stats["max_drawdown_median"])),
    ])
    st.markdown(f'<div class="mini-grid">{mini_html}</div>', unsafe_allow_html=True)




def _chart_layout(fig: go.Figure, title: str, height: int = 520) -> go.Figure:
    fig.update_layout(
        title=dict(text=title, x=0.02, xanchor="left", font=dict(size=21, color="#f8fafc")),
        font=dict(family="Inter, Segoe UI, Roboto, Arial, sans-serif", color="#cbd5e1"),
        height=height,
        hoverlabel=dict(bgcolor="#020617", bordercolor="rgba(125,211,252,.28)", font_size=13, font_color="#e5e7eb", font_family="Inter, Segoe UI, Roboto, Arial, sans-serif"),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(2,6,23,0.18)",
        margin=dict(l=64, r=28, t=68, b=64),
    )
    fig.update_xaxes(showgrid=True, gridcolor="rgba(148,163,184,.15)", zeroline=False, automargin=True, title_font=dict(size=13, color="#cbd5e1"), tickfont=dict(size=12, color="#94a3b8"), linecolor="rgba(148,163,184,.25)")
    fig.update_yaxes(showgrid=True, gridcolor="rgba(148,163,184,.15)", zeroline=False, automargin=True, title_font=dict(size=13, color="#cbd5e1"), tickfont=dict(size=12, color="#94a3b8"), linecolor="rgba(148,163,184,.25)")
    return fig


def build_distribution_chart(result: HistoricalSimulationResult, currency_symbol: str, target_wealth: float) -> go.Figure:
    df = pd.DataFrame({"Final wealth": result.final_values})
    fig = px.histogram(df, x="Final wealth", nbins=40, opacity=0.86)
    fig.update_traces(
        marker_color="#38bdf8",
        marker_line_color="rgba(255,255,255,.10)",
        marker_line_width=0,
        hovertemplate=f"Final wealth={currency_symbol}%{{x:,.0f}}<br>Windows=%{{y}}<extra></extra>",
    )
    fig.add_vline(x=float(result.stats["median"]), line_dash="dash", line_width=2, line_color="#f8fafc", annotation_text="Median", annotation_position="top", annotation_font_color="#f8fafc")
    fig.add_vline(x=float(result.stats["mean"]), line_dash="dot", line_width=2, line_color="#34d399", annotation_text="Mean", annotation_position="top", annotation_font_color="#bbf7d0")
    if target_wealth > 0:
        fig.add_vline(x=float(target_wealth), line_dash="solid", line_width=2, line_color="#fbbf24", annotation_text="Target", annotation_position="top right", annotation_font_color="#fde68a")
    fig.update_xaxes(title_text=f"Final wealth ({currency_symbol})", tickprefix=currency_symbol, separatethousands=True)
    fig.update_yaxes(title_text="Historical rolling windows")
    return _chart_layout(fig, f"Ending wealth distribution · {result.years} years", height=525)


